 $columns; } public function count_collected_posts($pid) { $count = $GLOBALS['QC']->cache->get_cache('count_collected_posts_' . $pid); if (!$count) { global $wpdb; $sql = "SELECT COUNT(*) FROM `$wpdb->posts` WHERE `ID` IN (
